    fullSolution_ar: `
1. **استغلال تتابع القواعد والشفرة:**
   - عند الشخص السليم: الرامزة 39 في السلسلة غير المستنسخة هي $CAG$، فتكون الرامزة المقابلة على الـ ARNm هي **$CAG$** وتشفر للحمض الأميني **الغلوتامين (Gln)**، مما يسمح باستمرار الترجمة وتشكل بروتين كامل يضم 146 حمضاً أمينياً.
   - عند الشخص المصاب: حدثت **طفرة استبدال** نكليوتيد $C$ بالنكليوتيد $T$ في الموقع 39 للمورثة، مما أدى لظهور الرامزة **$UAG$** على شريط الـ ARNm.
2. **الاستدلال والتفسير البيولوجي:**
   - الرامزة $UAG$ هي إحدى **رامزات التوقف الثلاث (Codon Stop)** التي لا يقابلها أي حمض أميني أو ARNt، مما يؤدي إلى انفصال الريبوزوم وتوقف الترجمة في مرحلة مبكرة جداً.
   - النتيجة: تركيب سلسلة ببتيدية قصيرة جداً (38 حمضاً أمينياً فقط بدل 146)، مما يفقدها القدرة على الانطواء واكتساب البنية الفراغية الطبيعية، فتصبح غير وظيفية وغير قادرة على نقل الأكسجين، مسببة فقر الدم الحاد.
`
