    coreConcept_ar: `
في أي سلسلة ببتيدية، المجموعات الكربوكسيلية والأمينية للجزء الثابت تكون منخرطة في الروابط الببتيدية ($-CO-NH-$) ولا تتأين.
المجموعات المسؤولة عن شحنة الببتيد هي حصراً:
1. **المجموعة الأمينية الطرفية الحرة ($-NH_2$)** في بداية السلسلة (N-terminal).
2. **المجموعة الكربوكسيلية الطرفية الحرة ($-COOH$)** في نهاية السلسلة (C-terminal).
3. **المجموعات الكربوكسيلية والأمينية الحرة المتواجدة في الجذور ($R$)** للأحماض الأمينية الحامضية والقاعدية المكونة للسلسلة.
`,
    simpleExplanation_ar: `
### خطوات حساب شحنة ببتيد في تمرين البكالوريا:
1. اكتب الصيغة المفصلة للجذور الحرة والنهايتين فقط:
   - النهاية الأمينية ($N$-term): $-NH_2$ (تتأين إلى $-NH_3^+$ في الوسط الحمضي).
   - النهاية الكربوكسيلية ($C$-term): $-COOH$ (تتأين إلى $-COO^-$ في الوسط القاعدي).
2. فحص الجذور $R$:
   - أحماض حامضية ($Asp, Glu$): جذورها تحوي $-COOH$ (تتأين إلى $-COO^-$ بشحنة $-1$ في الوسط المعتدل أو القاعدي).
   - أحماض قاعدية ($Lys, Arg, His$): جذورها تحوي $-NH_2$ (تتأين إلى $-NH_3^+$ بشحنة $+1$ في الوسط المعتدل أو الحمضي).
   - باقي الأحماض: جذورها لا تتأين (شحنتها دائماً $0$).
3. اجمع شحنات المجموعات المؤينة لحساب **الشحنة الصافية الإجمالية**.
`,
