export const snvWeek04Checkpoint: SnvWeeklyCheckpoint = {
  id: "snv_checkpoint_week04_peptide_charge_denaturation",
  title_ar: "المحطة الأسبوعية 04: تمرين استدلال علمي (حساب شحنة الببتيد وتأثير المسخ الكيميائي)",
  context_ar: `
أجريت دراسة بيوكيميائية على عديد ببتيد خطي معزول من بروتين غشائي، يمتلك التسلسل التالي للأحماض الأمينية:
$$H_2N - Ala - Glu - Lys - Cys - Gly - Asp - Val - COOH$$
علماً أن الجذور الجانبية ($R$) تحتوي على المجاميع التالية:
- $Glu$ (حمض الغلوتاميك): جذر حامضي يحتوي على $-COOH$.
- $Lys$ (الليسين): جذر قاعدي يحتوي على $-NH_2$.
- $Asp$ (حمض الأسبارتيك): جذر حامضي يحتوي على $-COOH$.
- باقي الأحماض ($Ala, Cys, Gly, Val$): جذور متعادلة لا تتأين مجاميعها في الظروف المدروسة.

تم وضع هذا الببتيد في محلول ذو باهاء معتدل $pH = 7.0$، ثم أُخضع لحقل كهربائي متواصل.
  `,
  taskStep: {
    instruction_ar: "1. حدد الصيغة الشاردية للمجاميع المتأينة في الببتيد عند pH = 7.0، ثم احسب الشحنة الكهربائية الإجمالية الصافية.\n2. استنتج مع التعليل اتجاه هجرة هذا الببتيد على شريط الهجرة الكهربائية.\n3. ما هو الأثر البنيوي لمعاملة بروتين يحوي هذا الببتيد بمركب اليوريا (Urée)؟",
    expectedKeywords: [
      "تأين النهايات والجذور",
      "الشحنة الإجمالية الصافية (-1)",
      "الهجرة نحو المصعد (القطب الموجب)",
      "تفكيك الروابط الهيدروجينية",
      "فقدان البنية الفراغية الثانوية والثالثية"
    ],
    fullSolution_ar: `
1. **حساب الشحنة الإجمالية الصافية عند pH = 7.0:**
   - **المجموعة الأمينية الطرفية ($N$-terminal):** تتأين إلى $-NH_3^+$ ➔ الشحنة = $+1$.
   - **المجموعة الكربوكسيلية الطرفية ($C$-terminal):** تتأين إلى $-COO^-$ ➔ الشحنة = $-1$.
   - **جذر حمض الغلوتاميك ($Glu$):** يتأين إلى $-COO^-$ ➔ الشحنة = $-1$.
   - **جذر حمض الأسبارتيك ($Asp$):** يتأين إلى $-COO^-$ ➔ الشحنة = $-1$.
   - **جذر حمض الليسين ($Lys$):** يتأين إلى $-NH_3^+$ ➔ الشحنة = $+1$.
   - **المحصلة الحسابية للشحنة الصافية:**
     $$\\text{الشحنة} = (+1) + (-1) + (-1) + (-1) + (+1) = -1$$
   - الببتيد يحمل **شحنة سالبة إجمالية صافية مقدارها ($-1$)**.

2. **اتجاه الهجرة الكهربائية:**
   - بما أن الشحنة الصافية سالبة ($-1$)، فإن عديد الببتيد يهاجر نحو **القطب الموجب (المصعد +)** بتأثير قوى التجاذب الكهروستاتيكية.

3. **أثر المعاملة باليوريا (Urée):**
   - اليوريا مركب كيميائي يفكك الروابط الضعيفة، وتحديداً **الروابط الهيدروجينية**.
   - يؤدي ذلك إلى انفراط حلزونات $\\alpha$ و وريقات $\\beta$ ومناطق الانعطاف، مما يفقد البروتين بنيته الفراغية الثانوية والثالثية، فيصبح عديم الفاعلية والنشاط الوظيفي (تمسخ بنيوي).
`
  },
  // تمرين توأم لمختبر الأخطاء (يظهر بعد 48 ساعة لمن تعثر في جرد الشحنات أو حساب الأطراف)
  twinRetest: {
    id: "snv_twin_week04_basic_peptide_migration",
    title_ar: "تمرين توأمي: تثبيت مهارة حساب شحنة الببتيدات الغنية بالقواعد",
    context_ar: `
ليكن عديد الببتيد التالي:
$$H_2N - Met - Arg - His - Ser - Lys - Gly - COOH$$
علماً أن الأحماض الثلاثة ($Arg, His, Lys$) تمتلك جذوراً قاعدية تتأين إلى مجاميع $-NH_3^+$ عند $pH = 5.0$.
    `,
    question_ar: "احسب الشحنة الصافية لهذا الببتيد عند pH = 5.0، وحدد القطب الذي يهاجر نحوه في جهاز الفصل الكهربائي.",
    correctAnswer_ar: `
**جرد الشحنات عند pH = 5.0:**
1. النهاية الأمينية الطرفية: $-NH_3^+$ ($+1$).
2. النهاية الكربوكسيلية الطرفية: $-COO^-$ ($-1$).
3. جذر الأرجنين ($Arg$): $-NH_3^+$ ($+1$).
4. جذر الهيستيدين ($His$): $-NH_3^+$ ($+1$).
5. جذر الليسين ($Lys$): $-NH_3^+$ ($+1$).
6. باقي الأحماض ($Met, Ser, Gly$): شحنتها معدومة ($0$).

**المحصلة الصافية:**
$$\\text{الشحنة} = (+1) + (-1) + (+1) + (+1) + (+1) = +3$$
- الشحنة الإجمالية **موجبة (+3)**.
- **اتجاه الهجرة:** يهاجر بسرعة نحو **القطب السالب (المهبط -)**.
`
  }
};

