export const snvUnit02CapstoneCheckpoint: SnvWeeklyCheckpoint = {
  id: "snv_checkpoint_unit02_sickle_cell_anemia",
  title_ar: "المحطة الكبرى لختم الوحدة 02: مسعى علمي كامل (فقر الدم المنجلي والدراسة البيوكيميائية للهيموغلوبين)",
  context_ar: `
يتميز مرض **فقر الدم المنجلي (Drépanocytose)** بتشوه كريات الدم الحمراء عند انخفاض ضغط الأكسجين ($O_2$) وتأخذ شكلاً منجلياً يسد الشعيرات الدموية، بسبب تراكم جزيئات الهيموغلوبين غير الطبيعي ($HbS$) في شكل ألياف صلبة غير قابلة للانحلال، عكس الهيموغلوبين الطبيعي ($HbA$) الذي يبقى منحلاً ومفرداً.
توضح الوثائق:
- **الوثيقة (1):** تتابع الأحماض الأمينية الأولى لسلسلة بيتا:
  - $HbA$: Val - His - Leu - Thr - Pro - **Glu** - Lys ... (الحمض 6 هو حمض الغلوتاميك القطبي المشحون سلباً المحب للماء).
  - $HbS$: Val - His - Leu - Thr - Pro - **Val** - Lys ... (الحمض 6 هو الفالين اللاقطبي الكاره للماء).
- **الوثيقة (2):** نتائج الهجرة الكهربائية لمزيج من ($HbA$) و ($HbS$) عند باهاء وسط $pH = 8.6$ مع مسافات الهجرة نحو القطب الموجب.
  `,
  taskStep: {
    instruction_ar: `1. استغل معطيات الوثيقة (1) لتقديم تفسير بيوكيميائي لتشكل الألياف الصلبة غير المنحلة لـ HbS عند انخفاض O2 مقارنة بـ HbA.\n2. باستغلال الوثيقة (2)، حدد مع التعليل أي البروتينين يهاجر مسافة أطول نحو المصعد (+).`,
    expectedKeywords: [
      "استبدال حمض الغلوتاميك بالفالين",
      "جيب كاره للماء",
      "تكتل الجزيئات في ألياف صلبة",
      "اختلاف الشحنة الصافية السالبة",
      "هجرة أسرع للـ HbA"
    ],
    fullSolution_ar: `
1. **التفسير البيوكيميائي لتشكل الألياف الصلبة:**
   - يكمن الخلل في استبدال حمض أميني واحد في الموقع 6 لسلسلة بيتا: تم استبدال **حمض الغلوتاميك (Glu)** وهو حمض حامضي قطبي ومحب للماء بـ **الفالين (Val)** وهو حمض أميني لاقطبي كاره للماء.
   - عند انخفاض تركيز الأكسجين ($O_2$)، ينشأ على سطح جزيء الهيموغلوبين جيب أو بروز كاره للماء بوجود جذر الفالين.
   - لتفادي الوسط المائي الخلوي، يتجاذب جذر الفالين لجزيئة $HbS$ مع موقع كاره للماء في جزيئة $HbS$ مجاورة (Interactions hydrophobes)، مما يؤدي إلى **بلمرة وتكتل جزيئات الهيموغلوبين في شكل خيوط وألياف صلبة غير قابلة للذوبان**، مما يشوه بنية الكرية الحمراء ويجعلها منجلية صلبة تسد الأوعية.
   - في حالة $HbA$، وجود حمض الغلوتاميك المشحون المحب للماء يضمن تشكيل روابط هيدروجينية مع الماء المحيط ويمنع التكتل، فتبقى الجزيئات منفردة وذائبة.

2. **تحديد اتجاه ومسافة الهجرة الكهربائية عند pH = 8.6:**
   - عند $pH = 8.6$، يمتلك كلا البروتينين شحنة سالبة و يهاجران نحو **القطب الموجب (المصعد +)**.
   - **المقارنة والتحديد:** جزيء **$HbA$ يهاجر مسافة أطول وأسرع نحو المصعد** مقارنة بـ $HbS$.
   - **التعليل:** الهيموغلوبين $HbA$ يحتوي في سلسلتيه بيتا على حمضي غلوتاميك إضافيين مقارنة بـ $HbS$، وكل حمض غلوتاميك يحمل شحنة سالبة إضافية ($-COO^-$)، وبالتالي فإن المحصلة الشاردية السالبة الإجمالية لـ $HbA$ أكبر من المحصلة السالبة لـ $HbS$ (بمقدار شحنتين سالبتين)، مما يجعله أكثر تأثراً بقوة التجاذب نحو القطب الموجب.
`
  },
  // تمرين توأم لمختبر الأخطاء (يظهر بعد 48 ساعة لمن تعثر في فهم العلاقة بين استبدال الأحماض ومسافة الهجرة)
  twinRetest: {
    id: "snv_twin_unit02_hemoglobin_c",
    title_ar: "تمرين توأمي: تثبيت مهارة التنبؤ بنتائج الهجرة الكهربائية للهيموغلوبينات الطافرة",
    context_ar: `
يوجد نمط طافر آخر للهيموغلوبين يسمى **الهيموغلوبين C ($HbC$)**، وفيه يستبدل حمض الغلوتاميك في الموقع 6 لحمض بيتا بـ **حمض الليسين (Lys)** وهو حمض أميني قاعدي يحمل في الوسط المعتدل شحنة موجبة ($+$).
أجريت هجرة كهربائية عند $pH = 8.6$ لمزيج يحتوي على البروتينات الثلاثة ($HbA$ ، $HbS$ ، و $HbC$).
    `,
    question_ar: "رتب هذه البروتينات الثلاثة تصاعدياً حسب مسافة وسرعة هجرتها نحو القطب الموجب (المصعد)، مع تقديم تبرير شحني دقيق.",
    correctAnswer_ar: `
**الترتيب من الأقل هجرة إلى الأكثر هجرة نحو المصعد (+):**
$$HbC < HbS < HbA$$

**التبرير الشحني:**
1. **$HbC$ (الأبطأ هجرة):** فقد شحنة سالبة واكتسب شحنة موجبة (الليسين)، فتكون شحنته السالبة الصافية هي الأضعف بين الثلاثة.
2. **$HbS$ (متوسط الهجرة):** فقد شحنة سالبة لكنه استبدلها بحمض متعادل كهربائياً (الفالين)، فتكون شحنته السالبة أكبر من $HbC$ وأقل من $HbA$.
3. **$HbA$ (الأسرع والأبعد هجرة):** يمتلك حمض الغلوتاميك ذو الشحنة السالبة، وتكون محصلة شحنته السالبة الإجمالية هي الأعلى بين البروتينات الثلاثة، مما يجعله الأكثر انجذاباً نحو القطب الموجب.
`
  }
};

