    targetCapability_ar: "التفريق بين ظاهرتي الارتصاص والترسيب وتفسير تشكل الشبكة ثلاثية الأبعاد بين الأجسام المضادة والمستضدات متعددة المحددات.",
    coreConcept_ar: `
**المعقد المناعي (Complexe immun)** هو ناتج الارتباط النوعي بين الجسم المضاد ومحدد المستضد.
بما أن لكل جسم مضاد موقعي تثبيت، فإن بإمكانه ربط مستضدين في نفس الوقت؛ فإذا كان المستضد يملك محددات متعددة تتشكل شبكة جزيئية ثلاثية الأبعاد تؤدي إلى:
1. **الارتصاص (Agglutination):** إذا كان المستضد خلوياً كبيراً (بكتيريا أو كريات دم حمراء).
2. **الترسيب (Précipitation):** إذا كان المستضد جزيئاً كيميائياً ذائباً (سموم أو بروتينات مصلية).
`,
    simpleExplanation_ar: `
### الأهمية البيولوجية لتشكل المعقدات المناعية:
- **تعديل وإبطال مفعول التوكسين (Neutralisation):** حجب المواقع السامة للجزيء الغازي بفعل تغطيتها بمواقع الأجسام المضادة، مما يمنعها من الارتباط بمستقبلاتها الخلوية.
- **شل حركة البكتيريا ومنع تكاثرها:** تكتل المستضدات في كتل كبيرة يمنعها من الانتشار في أنسجة العضوية.
- **تسهيل وتسريع البلعمة (Opsonisation):** تكتل مئات المستضدات داخل معقدات يُمكّن البالعة الكبيرة من ابتلاعها دفعة واحدة بفضل وجود مستقبلات غشائية نوعية للجزء الثابت ($Fc$) للأجسام المضادة.
`,
