      labels: [
        { id: 1, text_ar: "مستضد خلوي متعدد المحددات" },
        { id: 2, text_ar: "أجسام مضادة نوعية مرتبطة بموقعيها" },
        { id: 3, text_ar: "شبكة الارتصاص المعطلة لانتشار المستضد" },
        { id: 4, text_ar: "المنطقة الثابتة Fc الحرة المهيأة للتثبت على البالعة" }
      ]
