  // ─── اليوم 40: مراحل البلعمة والتخلص من المعقد المناعي ─────────────────────
  {
    id: "snv_u04_d40_phagocytosis_steps",
    dayNumber: 40,
    subjectId: "sciences_naturelles",
    streamId: "sciences_exp",
    unitTitle_ar: "الوحدة 04: دور البروتينات في الدفاع عن الذات",
    title_ar: "مراحل البلعمة: التثبيت، الإحاطة، الابتلاع، الهضم، واطراح البقايا",
    targetCapability_ar: "وصف مراحل البلعمة وتوضيح دور المستقبلات الغشائية للبالعات للقطعة الثابتة Fc في التكامل وتسهيل البلعمة.",
    coreConcept_ar: `
تعتبر **البلعمة (Phagocytose)** المرحلة الختامية الأساسية لإقصاء المعقد المناعي وتطهير العضوية.
تمتلك البالعات الكبيرة على أغشيتها مستقبلات نوعية للقطعة الثابتة ($Fc$) للأجسام المضادة؛ ارتباط المعقد المناعي بهذه المستقبلات يحفز البالعة على تنشيط مراحل الهضم السريع.
`,
    simpleExplanation_ar: `
### المراحل الخمس المنظمة لبلعمة المعقد المناعي:
1. **المرحلة 1: التثبيت (Fixation):**
   - يتثبت المعقد المناعي على المستقبلات الغشائية للبالعة بفضل التكامل البنيوي بين موقع المستقبل والقطعة الثابتة ($Fc$) للجسم المضاد.
2. **المرحلة 2: الإحاطة وتشكيل الأرجل الكاذبة (Invagination):**
   - يمتد الغشاء الهيولي للبالعة مشكلاً امتدادات هيولية تسمى **الأرجل الكاذبة (Pseudopodes)** تحيط بالمعقد المناعي بالكامل.
3. **المرحلة 3: الابتلاع وتشكل حويصل البلعمة (Ingestion):**
   - تلتحم الأرجل الكاذبة فينحبس المعقد المناعي داخل فجوة بالعة مغلقة تدعى **حويصل البلعمة (Phagosome)**.
4. **المرحلة 4: الهضم الإنزيمي (Digestion):**
   - تندمج **اللييزوزومات (Lysosomes)** المحملة بإنزيمات محللة نشطة (كالبروتياز) مع الفجوة البالعة مشكلة *Phagolysosome*، فيتم تفكيك المعقد إلى ببتيدات دقيقة وجزيئات أولية.
5. **المرحلة 5: الإطراح الخلوي (Excrétion / Rejet des déchets):**
   - تهاجر الفجوة نحو الغشاء الهيولي وتلتحم به لتطرح الحطام غير المهضوم خارج الخلية، مع احتفاظ بعض الخلايا (CPA) بمحددات لتقديمها على جزيئات CMH-II.
`,
    diagram: {
      url: "/illustrations/curriculum/snv/phagocytosis_mechanism.svg",
      caption_ar: "رسم تخطيطي تفصيلي يوضح مراحل بلعمة وهضم المعقد المناعي بتدخل الليزوزومات",
      labels: [
        { id: 1, text_ar: "مستقبل غشائي للقطعة Fc على البالعة" },
        { id: 2, text_ar: "امتداد الأرجل الكاذبة حول المعقد" },
        { id: 3, text_ar: "حويصل البلعمة (Phagosome)" },
        { id: 4, text_ar: "اندماج حويصلات الليزوزوم الحاوية على إنزيمات هاضمة" },
        { id: 5, text_ar: "إطراح الفضلات بالنزح الخلوي" }
      ]
    },
    externalResource: {
      platform: "youtube",
      channelName: "الأستاذ خليل سعيد - علوم الطبيعة والحياة",
      title: "مراحل البلعمة الخمس وكيف ترسم مخططاً واضحاً يضمن النقطة في البكالوريا",
      videoUrl: "https://www.youtube.com/watch?v=M7m3X8vK2pQ",
      targetTimestamp: "06:10"
    },
    commonMistakes: [
      {
        trap_ar: "نسيان دور مستقبلات Fc في مرحلة التثبيت.",
        explanation_ar: "القول بأن البالعة تبتلع المعقد مباشرة دون ارتباط نوعي؛ تثبيت المعقد مشروط بوجود مستقبلات نوعية للقطعة الثابتة للجسم المضاد على غشاء البالعة.",
        remedy_ar: "مرحلة التثبيت تعتمد على: مستقبلات غشائية نوعية لـ Fc للبالعة + القطعة الثابتة للجسم المضاد."
      }
    ],
    quickRecallPrompt_ar: "ما هي العضية الخلوية المسؤولة عن إفراز الإنزيمات الهاضمة داخل حويصل البلعمة؟",
    quickRecallAnswer_ar: "الليزوزوم (Lysosome)."
  }
