    coreConcept_ar: `
لا تستطيع الخلية اللمفاوية $LT_8$ التعرف على المستضد الحر في السوائل؛ بل تشترط ظاهرة **التعرف المزدوج (Double reconnaissance)**:
يتعرف مستقبلها **$TCR$** نوعياً على **الببتيد المستضدي** المعروض وفي نفس الوقت يتعرف مؤشرها **$CD_8$** على جزيئة **$CMH-I$ الذاتية**.
`,
    simpleExplanation_ar: `
### شروط ومراحل تمايز LT8 إلى LTc سامة:
1. **التعرف المزدوج الحصري:**
   - تلتقي الخلية $LT_8$ بخلية عارضة للمستضد ($CPA$) أو خلية مصابة تعرض ببتيداً غريباً محمولاً على $CMH-I$.
   - يؤدي التعرف المزدوج إلى تنشيط الخلية وظهور مستقبلات هرمون **الأنترلوكين 2 (R-IL2)** على غشائها.
2. **التحفيز الكيميائي بالأنترلوكين 2:**
   - تفرز الخلايا المساعدة $LTh$ (المشتقة من $LT_4$) جزيئات $IL-2$ التي تثبت على مستقبلات $R-IL2$ للخلية $LT_8$ المنشطة.
3. **التكاثر والتمايز:**
   - تنقسم الخلية $LT_8$ خيطياً لتشكل لمة نسيلية متماثلة؛ يتمايز أغلبها إلى **خلايا لمفاوية تائية سامة ($LTc$ - Cytotoxique)** قادرة على التدمير، وأقلية تبقى كـ **خلايا تائية ذاكرة ($LT_8m$)**.
`,
