    coreConcept_ar: `
المنهجية الرسمية للبكالوريا ترتكز على **المهمة المركبة**: الفعل الأدائي يحدد خطة العمل التي ينتظرها المصحح في شبكة التقويم.
الخلط بين 'حلل' و 'فسر' أو تحويل الاستدلال إلى مجرد قراءة أرقام يؤدي إلى ضياع علامة المنهجية كاملة.
`,
    simpleExplanation_ar: `
### دليل التعامل مع الأفعال الأدائية الرسمية:
1. **حلل (Analyser):** قراءة وصفية موجهة للمعطيات (ماذا ألاحظ؟).
   - تعريف بالوثيقة + تفكيك المعطيات مع إبراز العلاقات الرياضية (تزايد، تناقص، ثبات) + استنتاج صريح يمثل الحقيقة المستخلصة.
2. **فسر (Expliquer / Interpréter):** البحث عن الأسباب والآليات البيولوجية (لماذا حدث ذلك؟ وكيف؟).
   - ربط النتيجة بالآلية الجزيئية (مثلاً: سبب انخفاض النشاط هو تغير الحالة الشاردية للموقع الفعال).
3. **صادق على صحة الفرضية (Valider une hypothèse):**
   - استغلال الوثيقة (تحليل + استنتاج) ➔ الربط المنطقي بين الاستنتاج والفرضية ➔ التصريح بالقول: *وهذا ما يؤكد ويثبت صحة الفرضية المقترحة*.
4. **بين / وضح / اشرح:** مهمة مركبة تستدعي استغلال معطيات السند وتجنيد المكتسبات المعرفية في فقرة علمية متناسقة.
`,
