    coreConcept_ar: `
امتحان العلوم لشعبة العلوم التجريبية مدته **4 ساعات ونصف (4h30)**.
النجاح لا يعتمد فقط على الحفظ، بل على **الإدارة الاستراتيجية للوقت**: 30 دقيقة لاختيار الموضوع المناسب بشكل قطعي، ثم تخصيص توقيت صارم لكل تمرين وفق سلم تنقيطه.
`,
    simpleExplanation_ar: `
### 1. خوارزمية الـ 30 دقيقة الأولى لحسم الموضوع:
- اقرأ **التمرين الثالث (تمرين المسعى العلمي - 8 نقاط)** في كلا الموضوعين أولاً، لأنه يمثل 40% من العلامة:
  - هل فهمت التجربة والمشكل المطروح؟ هل الفرضية واضحة لك؟
- افحص **التمرين الأول (تمرين الاسترجاع المعرفي - 5 نقاط)**: هل تتقن النص العلمي المطلوب والكلمات المفتاحية؟
- ضع جدول تنقيط تقديري سريع: اختر الموضوع الذي تضمن فيه أكبر عدد من النقاط **المؤكدة** وليس الموضوع الذي 'يبدو أسهل بالقراءة السطحية'.
- بمجرد الاختيار: **أغلق الموضوع الثاني تماماً وضعه جانباً ولا ترجع إليه إطلاقاً**.

### 2. التوزيع الزمني المثالي للساعات المتبقية (4 ساعات):
- **التمرين 1 (5 نقاط):** خصص له **50 دقيقة** (20 د للبيانات والاسترجاع + 30 د لكتابة النص العلمي مهيكلاً).
- **التمرين 2 (7 نقاط - الاستدلال العلمي):** خصص له **ساعة و 15 دقيقة** (استغلال منظم للوثائق وإجابة المهمة المركبة).
- **التمرين 3 (8 نقاط - المسعى العلمي):** خصص له **ساعة و 35 دقيقة** (تفكيك الفرضيات والتجارب والمصادقة والخلاصة التركيبية).
- **المراجعة والتنقيح النهائي:** **20 دقيقة** لمراجعة ترقيم الأجوبة، الوحدات، وسلامة المصطلحات العلمية.
`,
    externalResource: {
      platform: "youtube",
      channelName: "الأستاذ خليل سعيد - علوم الطبيعة والحياة",
      title: "كيف تدير وقت امتحان العلوم وتختار الموضوع الصحيح وتتجنب فخ تغيير الموضوع في المنتصف",
      videoUrl: "https://www.youtube.com/watch?v=V7n4M8vL9xW",
      targetTimestamp: "07:50"
    },
