export const snvWeek11Checkpoint: SnvWeeklyCheckpoint = {
  id: "snv_checkpoint_week11_sarcoma_pd1_immunotherapy",
  title_ar: "المحطة الأسبوعية 11: مسألة إدماجية كبرى (العلاج المناعي للسرطان وتثبيط نقط التفتيش المناعية PD-1 / PD-L1)",
  context_ar: `
تتميز الخلايا السرطانية بقدرتها على الهروب من رقابة وتدمير الخلايا اللمفاوية التائية السامة ($LTc$) رغم عرضها لببتيدات مستضدية شاذة على جزيئات $CMH-I$.
أظهرت الدراسات الحديثة أن الخلايا الورمية تطور حيلة جزيئية تتمثل في تركيب بروتين غشائي يدعى **$PD-L1$**، يرتبط بمستقبل غشائي على سطح خلايا $LTc$ النشطة يدعى **$PD-1$** (مستقبل نقطة التفتيش المناعية)، مما يرسل إشارة كابحة توقف إفراز البيرفورين وتشل قدرتها على القتل السمي.
لعلاج هؤلاء المرضى، طُوّر دواء حديث يدعى **البمبروليزوماب (Pembrolizumab)**، وهو عبارة عن جسم مضاد أحادي النسيلة موجه نوعياً ضد مستقبل $PD-1$.
  `,
  taskStep: {
    instruction_ar: `1. استغل المعطيات لتقديم تفسير جزيئي لآلية هروب الخلايا السرطانية من الجهاز المناعي.\n2. اشرح كيف يساهم العلاج بجسم البمبروليزوماب المضاد في استعادة الجهاز المناعي لقدرته على القضاء على الورم.`,
    expectedKeywords: [
      "ارتباط PD-L1 بمستقبل PD-1",
      "إشارة تثبيطية كابحة",
      "شل إفراز البيرفورين",
      "حجب موقع الارتباط بالدواء",
      "استعادة النشاط السمي لـ LTc"
    ],
    fullSolution_ar: `
1. **التفسير الجزيئي لهروب الخلايا السرطانية:**
   - رغم حدوث التعرف المزدوج بين مستقبل $TCR$ لخلايا $LTc$ والمعقد ($CMH-I$ + ببتيد ورمي)، تعمد الخلية السرطانية إلى تنشيط بروتينها الغشائي **$PD-L1$**.
   - يرتبط $PD-L1$ بالمستقبل التثبيطي **$PD-1$** الموجود على غشاء الخلية $LTc$.
   - يُحدث هذا الارتباط **إرسال إشارات تأشير داخلية مثبطة** توقف تنشيط الخلية التائية وتمنع هجرة وإفراغ حويصلات **البيرفورين والغرونزيم**، مما يضع الخلية $LTc$ في حالة عجز وشلل وظيفي (Exhaustion immunitaire) يمنعها من إحداث الصدمة الحلولية، فتفلت الخلايا السرطانية وتتكاثر بحرية.

2. **آلية عمل دواء البمبروليزوماب (العلاج المناعي):**
   - دواء البمبروليزوماب هو جسم مضاد نوعي يتثبت بموقعه المتغير على مستقبلات **$PD-1$** للخلية اللمفاوية $LTc$.
   - يؤدي هذا التثبت إلى **الحجب الفراغي لمستقبل PD-1**، مما يمنع جزيئات $PD-L1$ للخلية السرطانية من الارتباط به.
   - زوال الإشارة التثبيطية الكابحة يسمح للخلية $LTc$ بـ **استعادة قدرتها التحفيزية ونشاطها السمي كاملاً**، فتقوم بإفراز البيرفورين في الشق المشبكي وإحداث الثقوب والصدمة الحلولية محفزة الموت المبرمج للخلايا السرطانية والقضاء على الورم.
`
  },
  // تمرين توأم لمختبر الأخطاء (يظهر بعد 48 ساعة لمن تعثر في فهم استهداف مستقبلات الخلايا التائية)
  twinRetest: {
    id: "snv_twin_week11_ctla4_checkpoint",
    title_ar: "تمرين توأمي: تثبيت مهارة فك آليات الكبح المناعي وعلاج السرطان بـ Anti-CTLA-4",
    context_ar: `
جزيء **$CTLA-4$** هو مستقبل تثبيطي يظهر على أغشية اللمفاويات التائية المساعدة $LT_4$ أثناء تنشيطها في العقد اللمفاوية؛ حيث ينافس مستقبل التنشيط $CD28$ ويرتبط بجزيئات $B7$ على سطح الخلية العارضة $CPA$، مما يوقف إفراز الأنترلوكين 2 (IL-2) ويثبط التكاثر.
    `,
    question_ar: "ما هي النتيجة المناعية المباشرة لحقن جسم مضاد يسد مستقبلات CTLA-4 نوعياً؟",
    correctAnswer_ar: `
يؤدي حجب مستقبلات CTLA-4 بواسطة الجسم المضاد إلى منع ارتباطها بجزيئات B7 للخلية العارضة، مما يسمح لمستقبل التنشيط CD28 بالارتباط المستمر وإرسال إشارات تنشيط دائمة، فينتج عن ذلك **استمرار وتكثيف إفراز الأنترلوكين 2 (IL-2)** وتضخيم هائل لتكاثر وتمايز الخلايا اللمفاوية ($LT_4$ و $LT_8$) مما يعزز الاستجابة المناعية ضد الأورام.`
  }
};

